pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        address alice = address(0x1234);
        vm.deal(alice, 1 ether);
        vm.prank(alice);
        c.getFirstWithdrawalBonus(alice);
        // rewardsForA is private, no getter; use the public _locked state to check reentrancy status
        // Actually, the property states the difference is in rewardsForA, which is private.
        // But we can observe the difference through a second call — in the reference it reverts (already claimed),
        // in the bug it succeeds because rewardsForA[alice] is still 100, and the claim check not reset.
        // However, the instructions say 'already tried' for the two-call approach. Let's use a different observable:
        // Check the _locked variable — after the call it should be false in both, so that doesn't work.
        // Instead, use a try/catch on a second call to getFirstWithdrawalBonus:
        bool secondCallSucceeded;
        try c.getFirstWithdrawalBonus(alice) { secondCallSucceeded = true; } catch { secondCallSucceeded = false; }
        // Reference: second call reverts (claimedBonus true) => secondCallSucceeded == false
        // Bug: second call succeeds because rewardsForA reset missing, but claimedBonus check prevents it...
        // Hmm, claimedBonus[alice] is true after first call, so second call reverts in both due to claimedBonus check.
        // This can't distinguish. Need another approach: observe address(c).balance after two calls?
        // Actually, the difference manifests in ETH sent: reference sends 100 wei once; bug sends 100 wei twice.
        // Let's reinitialize: call getFirstWithdrawalBonus(alice) twice, but intercept the first call's revert.
        // The key is that after first call, rewardsForA[alice] is 0 in reference, 100 in bug.
        // Then a second attempt via a different function? No, the only entry is getFirstWithdrawalBonus.
        // Let's observe the ETH balance of alice after one call: reference sends 100 wei; bug sends 100 wei.
        // Same. Need a scenario where the bug sends more ETH.
        // The 'already tried' two-call approach fails because claimedBonus blocks. 
        // Let's try: call getFirstWithdrawalBonus(alice), then use a contract that calls withdrawReward directly?
        // withdrawReward is external, but can be called separately. After first call, in reference rewardsForA[alice]=0,
        // so withdrawReward(alice) sends 0, in bug sends 100.
        // Let's do that:
        vm.prank(alice);
        c.getFirstWithdrawalBonus(alice);
        uint balanceBefore = alice.balance;
        vm.prank(alice);
        c.withdrawReward(alice);
        uint balanceAfter = alice.balance;
        // Reference: second withdraw sends 0 => balanceAfter == balanceBefore
        // Bug: second withdraw sends 100 wei => balanceAfter - balanceBefore == 100
        assertTrue(balanceAfter == balanceBefore, "Reference should send no extra ETH");
    }
}

