pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        address alice = address(0x1234);
        vm.deal(alice, 1 ether);

        // First call: both reference and bug will send 100 wei to alice
        vm.prank(alice);
        c.getFirstWithdrawalBonus(alice);

        // After first call, in reference rewardsForA[alice] = 0, in bug it's 100
        uint aliceBalanceBefore = alice.balance;

        // Second withdrawReward call: reference reverts (no reward), bug sends another 100
        vm.prank(alice);
        (bool ok, ) = address(c).call(abi.encodeWithSignature("getFirstWithdrawalBonus(address)", alice));

        // In reference: second call reverts (claimedBonus true), ok = false
        // In bug: second call also reverts (claimedBonus true), same result
        // Instead, call withdrawReward directly (it's public via _nonReentrant)
        // Actually withdrawReward is public, so call it directly:
        vm.prank(alice);
        (bool ok2, ) = address(c).call(abi.encodeWithSignature("withdrawReward(address)", alice));

        // Reference: rewardsForA[alice] = 0, so withdrawReward sends 0 wei, ok2 = true (but no transfer? Actually require(success) will succeed with 0 value)
        // Bug: rewardsForA[alice] = 100, so withdrawReward sends 100 wei, ok2 = true
        // This does not differentiate. Need different approach.

        // Let's check the balance difference more directly:
        // After first getFirstWithdrawalBonus, reference leaves rewardsForA[alice] = 0, bug leaves 100
        // So if we call withdrawReward again, reference will try to send 0 wei (succeeds), bug sends 100 (succeeds too)
        // Actually the revert scenario is different: we need a second getFirstWithdrawalBonus call that reverts in reference due to already claimed

        // Reset state for clean test:
        // Redo: deploy fresh
        c = new C();
        vm.deal(alice, 1 ether);

        // Call getFirstWithdrawalBonus once: reference: rewardsForA[alice] ends as 0, bug ends as 100
        vm.prank(alice);
        address(c).call(abi.encodeWithSignature("getFirstWithdrawalBonus(address)", alice));

        // Now call withdrawReward directly: reference will send 0 (succeeds), bug sends 100 (succeeds)
        // But we can detect by checking alice.balance difference
        uint balBefore = alice.balance;
        vm.prank(alice);
        (bool success, ) = address(c).call(abi.encodeWithSignature("withdrawReward(address)", alice));
        require(success, "withdrawReward failed");
        uint balAfter = alice.balance;

        // In reference: alice gets 0 extra (balAfter - balBefore == 0)
        // In bug: alice gets 100 extra (balAfter - balBefore == 100)
        // But this is not revert-based, need assertTrue
        // Actually the test must end with one assertTrue that reference holds and bug breaks
        // Reference: balAfter == balBefore (since rewardsForA was 0)
        // Bug: balAfter == balBefore + 100
        // So assertTrue(balAfter == balBefore) passes on reference, fails on bug

        // Wait: reference sends 0 wei, but that still succeeds (require(success) passes)
        // So balAfter == balBefore in reference, balAfter == balBefore + 100 in bug
        assertTrue(alice.balance == (balBefore));
    }
}

