pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        address alice = address(0x1234);
        vm.deal(alice, 0);

        // First call: getFirstWithdrawalBonus(alice)
        vm.prank(alice);
        c.getFirstWithdrawalBonus(alice);

        // Second call: withdrawReward(alice) — should revert in reference (rewardsForA[alice] == 0) but succeed in bug (rewardsForA[alice] == 100)
        bool success;
        vm.prank(alice);
        (success, ) = address(c).call(abi.encodeWithSignature("withdrawReward(address)", alice));

        // In reference, alice gets no second withdrawal (revert), so alice.balance == 100 (first bonus)
        // In bug, alice gets second withdrawal, so alice.balance > 100
        assertTrue(alice.balance == 100);
    }
}

