contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        // Set up: give the contract some ETH to pay out
        address recipient = address(0xBEEF);
        vm.deal(address(c), 200 wei);

        // First call: should succeed in both versions
        vm.prank(recipient);
        c.getFirstWithdrawalBonus(recipient);

        // Second call with same recipient: reference reverts (claimedBonus already true), buggy does not
        bool ok;
        try c.getFirstWithdrawalBonus(recipient) { ok = true; } catch { ok = false; }

        // Reference contract: second call reverts => ok is false
        // Buggy contract: second call succeeds => ok is true
        assertTrue(ok == false, "Second call should revert due to claimedBonus guard");
    }
}

